pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposit, uint256 extraDeposit) public {
        // Restrict to reasonable amounts to avoid overflow in setup
        vm.assume(initialDeposit > 0);
        vm.assume(extraDeposit > 0);
        vm.assume(initialDeposit <= type(uint128).max);
        vm.assume(extraDeposit <= type(uint128).max);
        vm.assume(initialDeposit + extraDeposit <= type(uint128).max);

        // Owner is this test contract (default)
        address owner = address(this);
        // Fund the owner
        vm.deal(owner, initialDeposit + extraDeposit);
        // Make deposits via fallback
        (bool s1,) = address(c).call{value: initialDeposit}("");
        require(s1, "deposit1 failed");
        (bool s2,) = address(c).call{value: extraDeposit}("");
        require(s2, "deposit2 failed");

        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;
        // Call withdrawAll
        c.withdrawAll();
        uint256 ownerBalanceAfter = owner.balance;
        uint256 contractBalanceAfter = address(c).balance;

        // Reference: owner's balance should increase exactly by the contract's balance before the call
        // Bug: mutant does nothing, so owner balance does not increase and contract balance remains unchanged
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + contractBalanceBefore);
    }
}

